<script>
    import { onMount } from 'svelte';
    export let api; export let state; export let datasets = []; export let saveDownload;
    let models = [], datasetId = '', modelId = '', scope = 'full', selectedComponent = '', exposure = '', prefix = '', prefixTouched = false, format = 'csv';
    let loading = true, error = '', check = null, preview = null, downloadMetadata = null, checking = false, downloading = false, inspection = false, request = 0, lastSelection = '';
    $: readyDatasets = datasets.filter((item) => item.status === 'available');
    $: if (!readyDatasets.some((item) => item.id === datasetId)) datasetId = readyDatasets[0]?.id || '';
    $: if (!models.some((item) => item.id === modelId)) modelId = models[0]?.id || '';
    $: dataset = readyDatasets.find((item) => item.id === datasetId);
    $: model = models.find((item) => item.id === modelId);
    $: scopeOptions = (model?.scopes || [{ id:'model' }, { id:'through' }, { id:'full' }]).map((item) => ({
        ...item,
        label: item.id === 'model' ? 'This model’s contribution' : item.id === 'through' ? 'Combined prediction through this model' : item.id === 'full' ? 'Full-chain prediction' : 'Catalogue candidate output',
        description: item.id === 'model' ? 'The selected accepted component scope, using its fitted basis.' : item.id === 'through' ? 'The cumulative prediction from the start of the accepted chain through the selected checkpoint.' : item.id === 'full' ? 'The complete prediction for this selected fitted version.' : 'A refreshed catalogue-master output for review only.',
    }));
    $: if (!scopeOptions.some((item) => item.id === scope)) scope = scopeOptions[0]?.id || 'full';
    $: components = model?.through_components || [];
    $: selectableComponents = scope === 'catalogue' ? components.filter((item) => item.kind === 'catalogue') : components;
    $: if (!selectableComponents.some((item) => item.component_id === selectedComponent)) selectedComponent = selectableComponents.at(-1)?.component_id || '';
    $: selectedIsRoot = model?.kind === 'logical' ? (model?.owned_component_ids || []).includes(model?.root_component_id) : selectedComponent === model?.root_component_id;
    $: exposureOptions = (model?.allowed_exposure_columns || (model?.exposure_column ? [model.exposure_column] : [])).filter((column) => (dataset?.columns || []).some((item) => item.name === column));
    $: if (exposure && !exposureOptions.includes(exposure)) exposure = '';
    $: prefixIdentity = (['model', 'through', 'catalogue'].includes(scope) && selectedComponent ? components.find((item) => item.component_id === selectedComponent)?.name : model?.name) || 'score';
    $: suggestedPrefix = `easyglm_${prefixIdentity.replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '').toLowerCase()}_${scope}_`;
    $: if (!prefixTouched) prefix = suggestedPrefix;
    $: payload = ({ session_id:state?.session_id, revision:state?.revision, dataset_id:datasetId, model_id:modelId, scope, component_ids: scope === 'model' ? (model?.kind === 'physical' && selectedComponent ? [selectedComponent] : model?.owned_component_ids || []) : scope === 'catalogue' && selectedComponent ? [selectedComponent] : [], through: scope === 'through' ? selectedComponent : null, exposure_col:exposure || null, column_prefix:prefix });
    $: scoreDetails = {
        dataset: dataset ? { id: dataset.id, name: dataset.name, filename: dataset.filename, digest: dataset.digest, version: dataset.version } : null,
        saved_fitted_version: model ? { id: model.id, name: model.name, fit_id: model.fit_id, accepted_through: model.through } : null,
        output: { scope, scope_label: scopeOptions.find((item) => item.id === scope)?.label, component_ids: payload.component_ids, component_names: components.filter((item) => payload.component_ids.includes(item.component_id) || item.component_id === payload.through).map((item) => item.name || item.component_id), through: payload.through, exposure_column: payload.exposure_col, column_prefix: payload.column_prefix },
        frozen_score: downloadMetadata || preview?.metadata?.pinned || check?.pinned || null,
        preflight_warnings: check?.warnings || [],
        preview_warnings: preview?.warnings || [],
    };
    $: checkReady = check?.ready === true && !(check?.issues || []).length;
    $: selectionKey = `${state?.revision}|${datasetId}|${dataset?.digest}|${dataset?.version}|${modelId}|${scope}|${selectedComponent}|${exposure}|${prefixTouched ? prefix : ''}`;
    $: if (selectionKey !== lastSelection) {
        lastSelection = selectionKey;
        request += 1;
        check = null;
        preview = null;
        downloadMetadata = null;
        checking = false;
    }
    async function load() { loading = true; try { const response = await api('scoring/models'); models = response.models || []; } catch (e) { error=e.message; } finally { loading=false; } }
    function issueText(issue) {
        if (typeof issue === 'string') return issue;
        const fields = issue.columns || issue.column || issue.values || issue.examples;
        return [issue.message || issue.detail || 'Input cannot be used for this saved score.', fields ? Array.isArray(fields) ? fields.join(', ') : fields : '', issue.dependency ? `Required by ${issue.dependency}.` : ''].filter(Boolean).join(' ');
    }
    async function checkInputs(previewOnly = false) { if (!datasetId || !modelId) return; const active=++request; checking=true; error=''; try { const result = await api(previewOnly ? 'scoring/preview' : 'scoring/check', payload); if (active !== request) return; if (previewOnly) preview=result; else { check=result; preview=null; } } catch(e) { if(active===request) error=e.message; } finally { if(active===request) checking=false; } }
    async function download() { if (!check || downloading) return; const active = ++request; const frozenPayload = structuredClone(payload); const frozenDetails = structuredClone(scoreDetails); downloading=true; error=''; try { const file=await api(`scoring/export?format=${encodeURIComponent(format)}`, frozenPayload, true); if (active !== request) return; saveDownload(file.blob,file.filename); downloadMetadata = file.scoringMetadata ? JSON.parse(file.scoringMetadata) : null; if (downloadMetadata) downloadDetails(`${file.filename}.metadata.json`, downloadMetadata, frozenDetails); } catch(e) { if (active === request) error=e.message; } finally { if (active === request) downloading=false; } }
    function downloadDetails(filename = '', frozen = null, details = scoreDetails) {
        const name = filename || `${dataset?.name || 'scoring'}_${model?.name || 'model'}_score_details.json`.replace(/[^A-Za-z0-9._-]+/g, '_');
        saveDownload(new Blob([JSON.stringify({ ...details, frozen_score: frozen || details.frozen_score }, null, 2)], { type: 'application/json' }), name);
    }
    onMount(load);
</script>

<section class="workflow-page score-new-data"><div class="heading"><div><h1>Score on new data</h1><p>Score a separate dataset with a frozen saved model. This does not refit or change any accepted model.</p></div></div>
{#if error}<div class="message error" role="alert">{error}</div>{/if}
{#if loading}<p>Loading saved fitted versions…</p>{:else if !readyDatasets.length || !models.length}<section class="model-card"><h2>{!readyDatasets.length ? 'Add a scoring dataset' : 'Fit and save a model first'}</h2><p>{!readyDatasets.length ? 'Go to Project & data and add a separate CSV or Parquet scoring dataset.' : 'A saved fitted version is needed before this dataset can be scored.'}</p></section>{:else}
<section class="model-card score-section"><h2><span>1</span> Dataset</h2><label>Scoring dataset<select aria-label="Scoring dataset" bind:value={datasetId}>{#each readyDatasets as item}<option value={item.id}>{item.name}</option>{/each}</select></label>{#if dataset}<div class="score-summary"><strong>{dataset.name}</strong> · {dataset.filename || dataset.path || 'Uploaded file'} · {dataset.rows?.toLocaleString()} rows · {dataset.columns?.length} columns <button onclick={() => (inspection=!inspection)}>Inspect columns</button></div>{#if inspection}<div class="inspect-columns">{#each dataset.columns || [] as column}<span>{column.name} <small>{column.dtype}</small></span>{/each}</div>{/if}{/if}</section>
<section class="model-card score-section"><h2><span>2</span> Saved fitted model</h2><label>Saved fitted version<select aria-label="Saved fitted version" bind:value={modelId}>{#each models as item}<option value={item.id}>{item.name}</option>{/each}</select></label>{#if model}<div class="identity-card"><strong>{model.name}</strong><span>Fitted version: <code>{model.fit_id || model.id}</code></span><span>Accepted recipe: {(model.through_components || []).map((item) => item.name || item).join(' → ') || 'Saved fitted model'}</span></div>{/if}</section>
<section class="model-card score-section"><h2><span>3</span> What to produce</h2><fieldset><legend>Output scope</legend><div class="scope-options">{#each scopeOptions.filter((item) => item.id !== 'catalogue') as item}<label class:chosen={scope===item.id}><input type="radio" bind:group={scope} value={item.id} /><strong>{item.label}</strong><span>{item.description}</span></label>{/each}</div></fieldset>{#if ['through', 'catalogue'].includes(scope) || (scope === 'model' && model?.kind === 'physical')}<label>{scope === 'through' ? 'Accepted checkpoint' : scope === 'catalogue' ? 'Catalogue component' : 'Accepted component'}<select aria-label="Accepted component" bind:value={selectedComponent}>{#each selectableComponents as component}<option value={component.component_id}>{component.name || component.component_id}</option>{/each}</select></label>{/if}{#if scope === 'catalogue'}<p class="candidate-selected"><strong>Candidate catalogue output selected.</strong> Review only; it cannot replace the accepted lookup or chain.</p>{/if}{#if scope==='model'}<p class="contribution-note">{selectedIsRoot ? 'This root-level contribution includes its fitted level and accepted tables, but excludes any external incoming offset.' : 'This model’s additional multiplier is shown within its accepted fitted basis.'}</p>{/if}{#if model?.external_offset_column && ['full', 'through'].includes(scope)}<p class="help-text">Includes the saved incoming offset column <code>{model.external_offset_column}</code>.</p>{/if}{#if model?.catalogue_refresh_available && scope !== 'catalogue'}<div class="catalogue-candidate"><strong>Score refreshed catalogue master</strong><p>This scores the new master with the retained native catalogue model. Review only: it cannot change the accepted lookup or chain.</p><button onclick={() => (scope = 'catalogue')}>Score refreshed catalogue master</button></div>{:else if model?.catalogue_refresh_unavailable}<p class="help-text">This saved version contains its accepted lookup table but no retained native catalogue model. It can score policies with the accepted lookup; it cannot score a refreshed catalogue master.</p>{/if}{#if ['full', 'through'].includes(scope)}<label>Prediction basis<select aria-label="Prediction basis" bind:value={exposure}><option value="">Unit prediction — per unit exposure / policy-period response</option>{#if !model?.probability}{#each exposureOptions as column}<option value={column}>Expected amount using {column} once from this scoring book</option>{/each}{/if}</select></label>{/if}{#if model?.probability}<p class="help-text">This fitted model returns a probability. Expected amount is unavailable.</p>{/if}<label>Output column prefix <input aria-label="Output column prefix" placeholder={suggestedPrefix} bind:value={prefix} oninput={() => (prefixTouched = true)} /></label></section>
<section class="model-card score-section"><h2><span>4</span> Check, preview and download</h2><button class="primary" onclick={() => checkInputs()} disabled={checking}>{checking ? 'Checking inputs…' : 'Check inputs'}</button>{#if check}<div class:failed={!checkReady} class="check-result"><strong>{!checkReady ? 'Cannot score this dataset yet' : `Ready to score ${(check.rows || dataset?.rows || 0).toLocaleString()} rows`}</strong><p>{check.message || (!checkReady ? 'Fix the listed inputs, then check again.' : 'Required inputs are available. Training target and split fields are not needed for this score.')}</p>{#if check.requirements}<details><summary>Required inputs</summary><p>{(check.requirements.columns || []).join(', ')}</p>{#if check.requirements.prepared_columns?.length}<p>Saved transforms: {check.requirements.prepared_columns.join(', ')}</p>{/if}</details>{/if}{#if check.issues}{#each check.issues as issue}<p class="issue"><strong>{issue.category || issue.kind}</strong> {issueText(issue)}</p>{/each}{/if}{#if check.warnings}{#each check.warnings as warning}<p class="warning"><strong>{warning.category || warning.kind || 'Lookup coverage'}</strong> {issueText(warning)}</p>{/each}{/if}</div>{#if checkReady}<button onclick={() => checkInputs(true)} disabled={checking}>Preview first 20 rows</button>{#if preview}<div class="score-preview"><h3>{scope === 'catalogue' ? 'Candidate catalogue output' : 'Score preview'}</h3><p>First 20 rows in source order. Original columns are retained.</p>{#if preview.warnings?.length}{#each preview.warnings as warning}<p class="warning"><strong>{warning.category || warning.kind || 'Score warning'}</strong> {issueText(warning)}</p>{/each}{/if}<div class="preview-scroll"><table><thead><tr>{#each preview.columns || [] as column}<th>{column}</th>{/each}</tr></thead><tbody>{#each preview.rows || [] as row}<tr>{#each preview.columns || [] as column}<td>{row[column]}</td>{/each}</tr>{/each}</tbody></table></div><label>File format <span><input type="radio" bind:group={format} value="csv" /> CSV</span><span><input type="radio" bind:group={format} value="parquet" /> Parquet</span></label><div class="download-actions"><button class="primary" onclick={download} disabled={downloading}> {downloading ? 'Preparing download…' : 'Download scored data'}</button><button onclick={() => downloadDetails()}>Download score details JSON — records the exact frozen model, scoring dataset and selected scope.</button></div>{#if downloadMetadata?.pinned}<p class="download-proof">Downloaded frozen score · fit <code>{downloadMetadata.pinned.fit_id}</code> · scorer <code>{downloadMetadata.pinned.scorer_id}</code></p>{/if}</div>{/if}{/if}{/if}</section>{/if}</section>

<style>
.score-new-data { max-width:1100px; }.score-section { display:grid; gap:14px; }.score-section h2 span { display:inline-grid; place-items:center; width:22px; height:22px; margin-right:8px; border-radius:50%; background:#e3ebe6; color:#123e2d; font-size:12px; }.score-section > label { display:grid; gap:6px; max-width:680px; font-size:13px; }.score-section select,.score-section input { width:100%; }.score-summary,.identity-card,.check-result { display:grid; gap:5px; padding:12px; background:var(--surface-muted); border-radius:6px; }.score-summary button { width:max-content; margin-top:4px; }.identity-card code { user-select:all; }.inspect-columns { display:flex; flex-wrap:wrap; gap:8px; }.inspect-columns span { background:var(--surface-muted); padding:5px 7px; border-radius:4px; }.inspect-columns small { color:var(--muted); }.scope-options { display:grid; gap:9px; max-width:760px; }.scope-options label { display:grid; grid-template-columns:18px 1fr; gap:3px 9px; padding:12px; border:1px solid var(--border); border-radius:6px; }.scope-options label span { grid-column:2; color:var(--muted); }.scope-options label.chosen { border-color:#156347; background:#e6f2eb; }.contribution-note { padding:10px 12px; background:#fff6dd; color:#6e551c; border-left:3px solid #c49a3d; }.catalogue-candidate,.candidate-selected { padding:12px; border:1px solid #c49a3d; background:#fffaf0; border-radius:6px; }.catalogue-candidate p { margin:6px 0 10px; }.candidate-selected { color:#6e551c; }.check-result.failed { background:#fff1e9; }.issue { color:#8b4215; }.warning { padding:8px 10px; background:#fff6dd; color:#6e551c; border-left:3px solid #c49a3d; }.score-preview { display:grid; gap:12px; }.preview-scroll { overflow:auto; max-width:100%; border:1px solid var(--border); }.preview-scroll table { border-collapse:collapse; min-width:max-content; width:100%; }.preview-scroll th,.preview-scroll td { padding:7px 10px; border-bottom:1px solid var(--border); text-align:left; white-space:nowrap; }.preview-scroll th { background:var(--surface-muted); }.score-preview > label { display:flex; align-items:center; gap:10px; }.download-actions { display:flex; gap:8px; flex-wrap:wrap; } @media (max-width:797px) { .score-section > label { max-width:none; }.scope-options label { min-height:82px; }.score-preview > label { flex-wrap:wrap; }.score-preview button,.score-section > button { width:100%; }.download-actions { display:grid; }.download-actions button { width:100%; } }
</style>
